MODEL_NAMES <- c("NB","LDA","QDA")
train_model <- function(rows,features,class_count,name,prior_mode,epsilon,gamma) {
  p <- length(features)
  n <- length(rows)
  groups <- lapply(
      seq_len(class_count),
      function(k) lapply(Filter(function(r) r$y == k,rows),function(r) r$x[features])
  )
  counts <- lengths(groups)
  means <- lapply(groups,function(group) vapply(seq_len(p),function(j) ordered_sum(vapply(group,`[`,numeric(1),j))/length(group),numeric(1)))
  scatter <- lapply(seq_len(class_count),function(k) {
    result <- matrix(0,p,p)
    for (a in seq_len(p)) for (b in seq_len(p)) result[a,b] <- ordered_sum(vapply(groups[[k]],
      function(x) (x[a]-means[[k]][a])*(x[b]-means[[k]][b]),numeric(1)))
    result
  })
  center <- vapply(
      seq_len(p),
      function(j) ordered_sum(vapply(rows,function(r) r$x[features[j]],numeric(1)))/n,
      numeric(1)
  )
  variances <- vapply(
      seq_len(p),
      function(j) ordered_sum(vapply(rows,function(r) (r$x[features[j]]-center[j])^2,numeric(1)))/n,
      numeric(1)
  )
  priors <- if (prior_mode == "empirical") counts/n else rep(1/class_count,class_count)
  pooled <- matrix(0,p,p)
  for (a in seq_len(p)) for (b in seq_len(p)) pooled[a,b] <- ordered_sum(vapply(
      scatter,
      function(s) s[a,b],
      numeric(1)
  ))/(n-class_count)
  max_variance <- max(variances)
  added <- epsilon*max_variance
  covariance <- lapply(seq_len(class_count),function(k) {
    matrix <- matrix(0,p,p)
    for (a in seq_len(p)) for (b in seq_len(p)) matrix[a,b] <- if (name == "LDA") pooled[a,b] else
      if (name == "NB") { if (a == b) scatter[[k]][a,b]/counts[k]+added else 0 } else
      scatter[[k]][a,b]/(counts[k]-1)*(if (a == b) 1 else 1-gamma)
    matrix
  })
  factors <- lapply(covariance,cholesky_factor)
  determinants <- vapply(factors,log_determinant,numeric(1))
  list(name=name,features=features,counts=counts,means=means,scatter=scatter,center=center,variances=variances,
    priors=priors,pooled=pooled,max_variance=max_variance,added=added,covariance=covariance,
    factors=factors,determinants=determinants,epsilon=epsilon,gamma=gamma)
}
distances_vector <- function(model,vector) vapply(seq_along(model$means),
  function(k) quadratic_form(model$factors[[k]],vector-model$means[[k]]),numeric(1))
distances <- function(model,values) distances_vector(model,values[model$features])
infer_vector <- function(model,vector,costs=NULL) {
  q <- distances_vector(model,vector)
  normalizer <- length(vector)*log(2*pi)/2
  scores <- vapply(
      seq_along(q),
      function(k) log(model$priors[k])-normalizer-model$determinants[k]/2-q[k]/2,
      numeric(1)
  )
  predicted <- which.max(scores)
  maximum <- scores[predicted]
  exponentials <- exp(scores-maximum)
  total <- ordered_sum(exponentials)
  posterior <- exponentials/total
  log_posterior <- (scores-maximum)-log(total)
  decision <- if (is.null(costs)) predicted else which.min(vapply(seq_along(q),
    function(b) ordered_sum(posterior*costs[,b]),numeric(1)))
  list(
      predicted=predicted,
      posterior=posterior,
      log_posterior=log_posterior,
      confidence=max(posterior),
      decision=decision
  )
}
infer <- function(model,values,costs=NULL) infer_vector(model,values[model$features],costs)
predict_class <- function(model,values) infer(model,values)$predicted

ordered_sum <- function(values) {
  total <- 0
  for (value in values) total <- total+value
  total
}
dot_product <- function(a,b) ordered_sum(a*b)
cholesky_factor <- function(matrix) {
  n <- nrow(matrix)
  lower <- matrix(0,n,n)
  for (i in seq_len(n)) for (j in seq_len(i)) {
    k <- seq_len(j-1L)
    value <- matrix[i,j]-ordered_sum(lower[i,k]*lower[j,k])
    lower[i,j] <- if (i == j) sqrt(value) else value/lower[j,j]
  }
  lower
}
forward <- function(lower,right) {
  n <- length(right)
  result <- numeric(n)
  for (i in seq_len(n)) {
    k <- seq_len(i-1L)
    result[i] <- (right[i]-ordered_sum(lower[i,k]*result[k]))/lower[i,i]
  }
  result
}
backward <- function(lower,right) {
  n <- length(right)
  result <- numeric(n)
  for (i in rev(seq_len(n))) {
    k <- seq_len(n)[seq_len(n) > i]
    result[i] <- (right[i]-ordered_sum(lower[k,i]*result[k]))/lower[i,i]
  }
  result
}
log_determinant <- function(lower) 2*ordered_sum(log(diag(lower)))
quadratic_form <- function(lower,difference) {
  transformed <- forward(lower,difference)
  dot_product(transformed,transformed)
}
jacobi <- function(matrix) {
  n <- nrow(matrix)
  current <- matrix
  vectors <- diag(n)
  sweeps <- 0L
  repeat {
    squares <- numeric()
    for (a in seq_len(n-1L)) for (b in seq.int(a+1L,n)) squares <- c(squares,current[a,b]^2)
    if (sqrt(ordered_sum(squares)) < 1e-12 || sweeps == 50L) break
    for (a in seq_len(n-1L)) for (b in seq.int(a+1L,n)) {
      if (current[a,b] == 0) next
      theta <- (current[b,b]-current[a,a])/(2*current[a,b])
      sg <- if (theta >= 0) 1 else -1
      t <- sg/(abs(theta)+sqrt(theta*theta+1))
      co <- 1/sqrt(t*t+1)
      si <- t*co
      for (k in seq_len(n)) {
        if (k == a || k == b) next
        x <- current[k,a]
        y <- current[k,b]
        current[k,a] <- current[a,k] <- co*x-si*y
        current[k,b] <- current[b,k] <- si*x+co*y
      }
      w <- current[a,b]
      current[a,a] <- current[a,a]-t*w
      current[b,b] <- current[b,b]+t*w
      current[a,b] <- current[b,a] <- 0
      for (k in seq_len(n)) {
        x <- vectors[k,a]
        y <- vectors[k,b]
        vectors[k,a] <- co*x-si*y
        vectors[k,b] <- si*x+co*y
      }
    }
    sweeps <- sweeps+1L
  }
  list(values=diag(current),vectors=vectors,sweeps=sweeps)
}

real_text <- function(value) {
  text <- sprintf("%.4f",value)
  text[text == "-0.0000"] <- "0.0000"
  text
}
reals <- function(values) paste(real_text(values),collapse=" ")
fraction_text <- function(value) {
  if (is.null(value)) return("-")
  paste0(sprintf("%.0f",value[1L]),"/",sprintf("%.0f",value[2L])," ",real_text(value[1L]/value[2L]))
}
ratio_text <- function(a,b) fraction_text(reduced_fraction(a,b))
frame <- function(grid) {
  border <- paste0("+",strrep("-",ncol(grid)),"+")
  c(
      border,
      vapply(seq_len(nrow(grid)),function(i) paste0("|",paste(grid[i,],collapse=""),"|"),character(1)),
      border
  )
}
cell <- function(value,low,high,n) floor((value-low)/(high-low)*(n-1)+0.5)
join_sections <- function(sections) {
  lines <- character()
  for (section in sections) {
    if (length(lines)) lines <- c(lines,"")
    lines <- c(lines,section)
  }
  lines
}
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}
